import {VERSION,BODY_FIELDS,MEASUREMENT_UNIT,MACROS,uid,localDate,localTime,validDate,shiftDate,dayDistance,weekStart,timestamp,avg,emptyState,validateState,makeItem,sumMacros,analyze,weeklyRows,parseBackup,backupObject,toCSV} from './core.js';
import {BASE_FOODS} from './foods.js';
import * as storage from './storage.js';
import {createReport,printReport} from './reports.js';

const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>v==null?'—':Number(v).toLocaleString('fr-FR',{minimumFractionDigits:d,maximumFractionDigits:d});
const dateLabel=(s,short=false)=>validDate(s)?new Date(s+'T12:00:00').toLocaleDateString('fr-FR',short?{day:'2-digit',month:'2-digit'}:{weekday:'long',day:'numeric',month:'long',year:'numeric'}):'';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const icons={home:'<path d="m3 10 9-7 9 7v10h-6v-7H9v7H3Z"/>',meal:'<path d="M5 3v7m3-7v7m3-7v7M5 7h6M8 10v11M19 21V3c-4 3-4 8 0 9"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 2 10 8 15 6-5 13-10 8-15Z"/>',body:'<path d="M8 3c1 4 0 6-2 9-3 5-2 8 0 9m10-18c-1 4 0 6 2 9 3 5 2 8 0 9M7 12c3 2 7 2 10 0M8 4h8"/>',chart:'<path d="M3 3v18h18M7 15l4-5 4 3 6-8"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',edit:'<path d="m14 4 6 6M4 20l2-6L17 3l4 4-11 11Z"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',document:'<path d="M6 2h9l4 4v16H6ZM14 2v5h5M9 11h7M9 15h7M9 19h4"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.heart}</svg>`;
document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));

let db=emptyState(),selectedDay=localDate(),activePage='day',toastTimer,busy=false,loadError=false;
let editKind=null,editId=null,dirty=false,draftItems=[],selectedFood=null,editItemId=null,returnToMeal=null;
let bodyLimit=20,pendingInstall=null,waitingWorker=null,confirmResolve=null;
const noteDrafts=new Map();
let writeQueue=Promise.resolve();
const channel='BroadcastChannel' in window?new BroadcastChannel(storage.channelName):null;
const foodList=()=>[...BASE_FOODS,...db.foods];
const selectedEntries=kind=>db.entries.filter(e=>e.date===selectedDay&&(!kind||e.kind===kind)).sort((a,b)=>a.time.localeCompare(b.time));
const empty=message=>`<div class="empty"><div class="empty-mark">♡</div>${esc(message)}</div>`;

function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,5500);}
function notice(message,error=false){const e=document.createElement('div');e.className='notice'+(error?' error':'');e.textContent=message;$('system-notices').append(e);return e;}
async function commit(change,{recover=false}={}){
  const work=async()=>{
    if(loadError&&!recover)throw Error('Le journal local n’a pas pu être lu. Restaure une sauvegarde avant de continuer.');
    const next=structuredClone(db);await change(next);
    next.updatedAt=new Date(Math.max(Date.now(),(Date.parse(db.updatedAt)||0)+1)).toISOString();
    const clean=validateState(next);await storage.save(clean,recover?undefined:db.updatedAt);db=clean;loadError=false;channel?.postMessage({updatedAt:db.updatedAt});render();return clean;
  };
  const result=writeQueue.then(work);writeQueue=result.catch(()=>{});return result;
}
function download(name,content,type){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function goPage(page){activePage=page;document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!=='page-'+page);document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});render();window.scrollTo({top:0,behavior:'auto'});}
function mealView(view){['journal','library','favorites'].forEach(v=>$('meal-'+v).hidden=v!==view);document.querySelectorAll('[data-meal-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.mealView===view);b.setAttribute('aria-pressed',String(b.dataset.mealView===view));});renderLibrary();renderFavorites();}
function reviewView(view){['trends','report','data'].forEach(v=>$('review-'+v).hidden=v!==view);document.querySelectorAll('[data-review-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.reviewView===view);b.setAttribute('aria-pressed',String(b.dataset.reviewView===view));});if(view==='report'){if(!$('report-name').value)$('report-name').value=db.settings.reportName;if(!$('report-note').value)$('report-note').value=db.settings.reportNote;}renderAnalysis();renderData();}
function setDay(date){if(!validDate(date))return;selectedDay=date;$('day').value=date;bodyLimit=20;render();}

function entryHTML(e,timeline=false){
  let title='',description='',meta='';
  if(e.kind==='meal'){const total=sumMacros(e.items);title=e.name||e.meal;description=e.items.map(i=>`${i.name} · ${fmt(i.amount,1)} ${i.baseUnit} (${i.basis})`).join(' + ');meta=`${fmt(total.k)} kcal · P ${fmt(total.p,1)} · G ${fmt(total.c,1)} · L ${fmt(total.f,1)} g`;if(e.hunger!=null)meta+=` · faim ${fmt(e.hunger)}/10`;if(e.satiety!=null)meta+=` · satiété ${fmt(e.satiety)}/10`;}
  if(e.kind==='hunger'){title=`Faim ${fmt(e.intensity)}/10 · ${e.type}`;description=[...e.physical,...e.emotions,e.context].filter(Boolean).join(' · ');meta=e.period;}
  if(e.kind==='sport'){title=`${e.type} · ${fmt(e.duration)} min`;description=e.effort!=null?`Effort ressenti ${fmt(e.effort)}/10`:'';}
  const inner=`<div class="entry-heading"><div><time class="entry-time">${esc(e.time)}${e.kind==='meal'?' · '+esc(e.meal):''}</time><span class="entry-title">${esc(title)}</span></div><button data-action="edit-entry" data-id="${esc(e.id)}" class="edit-button" aria-label="Modifier ${esc(title)} à ${esc(e.time)}">${icon('edit')}</button></div>${description?`<p class="entry-description">${esc(description)}</p>`:''}${meta?`<div class="entry-meta">${esc(meta)}</div>`:''}${e.note?`<p class="entry-note">${esc(e.note)}</p>`:''}`;
  return timeline?`<article class="timeline-entry ${e.kind}"><span class="timeline-dot"></span>${inner}</article>`:`<article class="card">${inner}</article>`;
}
function renderDay(){const entries=selectedEntries(),meals=entries.filter(e=>e.kind==='meal'),s=sumMacros(meals.flatMap(e=>e.items));$('day-kcal').textContent=fmt(s.k);for(const k of ['p','c','f'])$('day-'+k).innerHTML=`${fmt(s[k])} <small>g</small>`;
  const complete=db.days[selectedDay]?.complete===true;$('day-complete').checked=complete;$('day-state').textContent=complete?'Journée complète':meals.length?'En cours':'À compléter';$('day-state').classList.toggle('complete',complete);
  const target=db.settings.kcal;$('target-progress').innerHTML=target?`<p class="target-line">Repère personnel · ${fmt(target)} kcal</p><div class="meter" role="meter" aria-label="Apports notés par rapport au repère" aria-valuemin="0" aria-valuemax="${target}" aria-valuenow="${Math.min(s.k,target)}"><span style="width:${Math.min(100,100*s.k/target)}%"></span></div>`:'';
  $('event-count').textContent=entries.length?entries.length+' note'+(entries.length>1?'s':''):'';$('timeline').innerHTML=entries.length?entries.map(e=>entryHTML(e,true)).join(''):empty('La page est encore blanche. Un repas ou une sensation, et ton journal commence.');
  const sports=entries.filter(e=>e.kind==='sport');$('day-sports').innerHTML=sports.length?`<p class="subtle"><strong>${sports.map(e=>esc(e.type)+' · '+fmt(e.duration)+' min').join('<br>')}</strong></p>`:'<p class="subtle">Pas de séance notée pour ce jour.</p>';
  $('activity-known').checked=db.days[selectedDay]?.activityKnown===true;$('day-note').value=noteDrafts.get(selectedDay)??db.days[selectedDay]?.note??'';
}
function renderMeals(){const items=selectedEntries('meal');$('meals-date').textContent=dateLabel(selectedDay);$('meal-list').innerHTML=items.length?items.map(e=>entryHTML(e)).join(''):empty('Note ton premier repas ou une collation.');}
function renderHunger(){const items=selectedEntries('hunger');$('hungers-date').textContent=dateLabel(selectedDay);$('hunger-list').innerHTML=items.length?items.map(e=>entryHTML(e)).join(''):empty('Une faim, une envie, ou rien du tout : chaque sensation peut être notée.');}
function renderLibrary(){const q=normalize($('library-search').value),category=$('library-category').value;const foods=foodList().filter(f=>normalize(f.name+' '+f.basis).includes(q)&&(!category||f.category===category)).sort((a,b)=>a.name.localeCompare(b.name,'fr'));
  $('library-list').innerHTML=foods.length?foods.slice(0,100).map(f=>`<article class="food-row"><button data-action="food-detail" data-id="${esc(f.id)}"><strong>${esc(f.name)} <span class="food-state">${esc(f.basis)}</span></strong><small>${fmt(f.k)} kcal · P ${fmt(f.p,1)} · G ${fmt(f.c,1)} · L ${fmt(f.f,1)} g /100 ${f.unit}</small></button>${db.foods.some(x=>x.id===f.id)?`<button data-action="edit-food" data-id="${esc(f.id)}" class="edit-button" aria-label="Modifier ${esc(f.name)}">${icon('edit')}</button>`:''}</article>`).join(''):empty('Aucun résultat. Tu peux ajouter ton produit avec son étiquette.');
}
function updateCategories(){const categories=[...new Set(foodList().map(f=>f.category))].sort(),v=$('library-category').value;$('library-category').innerHTML='<option value="">Toutes les familles</option>'+categories.map(c=>`<option>${esc(c)}</option>`).join('');$('library-category').value=categories.includes(v)?v:'';}
function renderFavorites(){const favorites=db.favorites;$('favorite-list').innerHTML=favorites.length?favorites.map(f=>`<article class="card"><div class="section-heading"><h2>${esc(f.name)}</h2><button data-action="delete-favorite" data-id="${esc(f.id)}" class="remove-button" aria-label="Supprimer le favori ${esc(f.name)}">×</button></div><p class="subtle">${f.items.map(i=>esc(i.name)+' · '+fmt(i.amount,1)+' '+i.baseUnit).join('<br>')}</p><p class="entry-meta">${fmt(sumMacros(f.items).k)} kcal · portions modifiables</p><button data-action="use-favorite" data-id="${esc(f.id)}" class="button secondary full">Reprendre ce repas</button></article>`).join(''):empty('Tes repas habituels auront bientôt leur place ici.');}

function chart(series,{unit='',minZero=false,description='Évolution des observations'}={}){
  const values=series.flatMap(s=>s.points).filter(p=>p.value!=null&&Number.isFinite(p.value));if(!values.length)return empty('Les premières observations dessineront cette courbe.');
  const w=360,h=200,left=38,right=14,top=20,bottom=36,dates=values.map(p=>new Date(p.date+'T12:00:00Z').getTime()),first=Math.min(...dates),last=Math.max(...dates),low=Math.min(...values.map(p=>p.value)),high=Math.max(...values.map(p=>p.value)),pad=Math.max((high-low)*.2,minZero?25:.5),lo=minZero?0:low-pad,hi=high+pad;
  const x=d=>left+(last===first?(w-left-right)/2:((new Date(d+'T12:00:00Z').getTime()-first)/(last-first))*(w-left-right)),y=v=>h-bottom-(v-lo)/(hi-lo)*(h-top-bottom);
  let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(description)}"><title>${esc(description)}</title>`;
  [0,.5,1].forEach(f=>{const v=lo+(hi-lo)*f,py=y(v);svg+=`<line x1="${left}" x2="${w-right}" y1="${py}" y2="${py}" stroke="#e9dce1"/><text x="${left-6}" y="${py+3}" text-anchor="end">${fmt(v,minZero?0:1)}</text>`;});
  series.forEach(s=>{const points=s.points.filter(p=>p.value!=null).sort((a,b)=>a.date.localeCompare(b.date));const path=points.map((p,i)=>`${i?'L':'M'}${x(p.date).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ');if(s.line!==false)svg+=`<path d="${path}" stroke="${s.color}" stroke-width="${s.width||2}" fill="none" stroke-linejoin="round" stroke-linecap="round"/>`;points.forEach(p=>svg+=`<circle cx="${x(p.date)}" cy="${y(p.value)}" r="${s.radius||3}" fill="${s.color}"><title>${esc(dateLabel(p.date))} : ${fmt(p.value,1)} ${esc(unit)}${p.count?' ('+p.count+' pesées)':''}</title></circle>`);});
  const firstDate=new Date(first).toISOString().slice(0,10),lastDate=new Date(last).toISOString().slice(0,10);svg+=`<text x="${left}" y="${h-12}">${esc(dateLabel(firstDate,true))}</text><text x="${w-right}" y="${h-12}" text-anchor="end">${esc(dateLabel(lastDate,true))}</text><text x="${left}" y="11">${esc(unit)}</text></svg>`;return svg;
}
function bodyPeriod(){const end=selectedDay;const start=$('body-range').value==='all'?'1900-01-01':shiftDate(end,-Number($('body-range').value)+1);return {start,end:$('body-range').value==='all'?'2200-12-31':end};}
function renderBody(){const field=$('body-field').value,{start,end}=bodyPeriod(),items=db.body.filter(b=>b.date>=start&&b.date<=end).sort((a,b)=>a.date.localeCompare(b.date)),points=items.filter(b=>b[field]!=null).map(b=>({date:b.date,value:b[field]})),unit=MEASUREMENT_UNIT(field),series=[{points,color:field==='weight'?'#c49aa9':'#75465d',line:field!=='weight',radius:3}];
  const weeks=weeklyRows(db,start,end).filter(w=>w.weight!=null);if(field==='weight')series.push({points:weeks.map(w=>({date:w.date,value:w.weight,count:w.weighings})),color:'#75465d',width:2.5});
  $('body-chart').innerHTML=chart(series,{unit,description:`${BODY_FIELDS[field]} : ${points.length} mesures. Les valeurs figurent dans le tableau et l’historique.`});
  $('body-change').textContent=points.length>1?(points.at(-1).value-points[0].value>0?'+':'')+fmt(points.at(-1).value-points[0].value,1)+' '+unit:points.length?'1 mesure':'À mon rythme';
  $('weight-weeks').innerHTML=weeks.length?`<div class="scroll-table"><table><caption class="sr-only">Moyennes du poids, semaine du lundi au dimanche</caption><thead><tr><th>Semaine du</th><th>Poids moyen</th><th>Pesées</th><th>Écart</th></tr></thead><tbody>${weeks.map((w,i)=>`<tr><td>${dateLabel(w.date,true)}<small>au ${dateLabel(shiftDate(w.date,6),true)}</small></td><td>${fmt(w.weight,2)} kg</td><td>${w.weighings}/7</td><td>${i>0&&dayDistance(weeks[i-1].date,w.date)===7?fmt(w.weight-weeks[i-1].weight,2)+' kg':'—'}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Moyenne des pesées disponibles dans la période affichée. Les jours manquants ne comptent pas pour zéro.</p>`:empty('Les pesées seront regroupées du lundi au dimanche.');
  const records=[...db.body].sort((a,b)=>b.date.localeCompare(a.date));$('body-list').innerHTML=records.length?records.slice(0,bodyLimit).map(b=>`<article class="measurement-card"><div class="entry-heading"><strong class="entry-title">${esc(dateLabel(b.date))}</strong><button data-action="edit-body" data-id="${esc(b.id)}" class="edit-button" aria-label="Modifier la mesure du ${esc(dateLabel(b.date))}">${icon('edit')}</button></div><div class="measurement-grid">${Object.keys(BODY_FIELDS).filter(k=>b[k]!=null).map(k=>`<span>${BODY_FIELDS[k]} <b>${fmt(b[k],1)} ${MEASUREMENT_UNIT(k)}</b></span>`).join('')}</div>${b.note?`<p class="entry-note">${esc(b.note)}</p>`:''}</article>`).join(''):empty('Le poids est facultatif. Tu peux ne noter que les mensurations.');$('more-body').hidden=records.length<=bodyLimit;
}
function validPeriod(start,end,maxDays=3660){if(!validDate(start)||!validDate(end)||start>end)throw Error('Choisis une date de début antérieure ou égale à la fin.');if(dayDistance(start,end)>maxDays)throw Error(`Choisis une période de ${maxDays+1} jours maximum.`);return {start,end};}
function renderAnalysis(){const start=$('analysis-start').value,end=$('analysis-end').value;let a;try{validPeriod(start,end);a=analyze(db,start,end);}catch(e){$('analysis-content').innerHTML=`<p class="notice error">${esc(e.message)}</p>`;return;}
  const insight=(text,note)=>`<div class="insight">${esc(text)}${note?`<small>${esc(note)}</small>`:''}</div>`;
  let html=`<section class="card"><h2>Ce que j’ai renseigné</h2><p class="subtle"><strong>${a.complete.length} journées alimentaires complètes</strong> sur ${dayDistance(start,end)+1} jours · ${a.hungers.length} notes de faim · ${a.weightCount} pesées.</p><div class="stat-grid"><div class="mini-stat"><strong>${fmt(a.means.k)}</strong><small>kcal / journée complète</small></div><div class="mini-stat"><strong>${fmt(a.means.p,1)} g</strong><small>protéines / journée complète</small></div><div class="mini-stat"><strong>${fmt(a.hungerMean,1)}/10</strong><small>faim moyenne observée</small></div><div class="mini-stat"><strong>${a.weightDelta>0?'+':''}${fmt(a.weightDelta,1)} kg</strong><small>première → dernière pesée</small></div></div><p class="subtle">Glucides : ${fmt(a.means.c,1)} g · lipides : ${fmt(a.means.f,1)} g / journée complète. Les repas partiels sont exclus de ces moyennes.</p></section>`;
  html+=`<section class="card"><h2>Mes apports au fil des jours</h2>${chart([{points:a.days.filter(d=>d.complete).map(d=>({date:d.date,value:d.k})),color:'#75465d'},{points:a.days.filter(d=>!d.complete&&d.meals>0).map(d=>({date:d.date,value:d.k})),color:'#c49aa9',line:false}],{unit:'kcal',minZero:true,description:'Apports notés par jour. Prune : journée complète ; rose : saisie partielle.'})}<div class="chart-legend"><span><i class="legend-dot"></i>Journée complète</span><span><i class="legend-dot rose"></i>Saisie partielle</span></div></section>`;
  html+=`<section class="card"><h2>À quels moments ?</h2>${a.hungers.length?a.hours.map(h=>`<div class="hour-row"><span>${h.name}<small class="subtle"> · ${h.count} notes</small></span><div class="hour-bar"><span style="width:${(h.mean??0)*10}%"></span></div><b>${fmt(h.mean,1)}</b></div>`).join(''):empty('Note quelques sensations pour voir les moments observés.')}<p class="subtle">Ce sont les faims saisies, pas toutes les faims de ta journée.</p></section>`;
  html+=`<section class="card"><h2>Repas, faim et mouvement</h2>`;
  if(a.timing.earlyN>=2&&a.timing.lateN>=2)html+=insight(`Faim moyenne : ${fmt(a.timing.early,1)}/10 dans les 2 heures après le dernier repas, et ${fmt(a.timing.late,1)}/10 entre 2 et 6 heures.`,`${a.timing.earlyN} et ${a.timing.lateN} sensations. Le rapprochement utilise les heures, y compris après minuit.`);
  else html+=insight('Le lien entre l’heure du repas et la faim apparaîtra avec davantage de notes.', 'Il faut au moins 2 sensations dans chacune des fenêtres : moins de 2 h et de 2 à 6 h après le dernier repas.');
  if(a.sport.withN>=2&&a.sport.withoutN>=2)html+=insight(`Faim moyenne les jours avec séance : ${fmt(a.sport.with,1)}/10 (${a.sport.withN} jours). Sans séance : ${fmt(a.sport.without,1)}/10 (${a.sport.withoutN} jours).`,'Moyenne des moyennes journalières. Seuls les jours où l’activité est renseignée et la faim notée sont comparés.');
  else html+=insight('Pour comparer les jours avec et sans séance, renseigne aussi tes journées sans sport.', 'Au moins 2 jours de chaque type avec une note de faim sont nécessaires. Une activité non renseignée reste inconnue.');
  a.satiety.slice(0,3).forEach(s=>html+=insight(`${s.name} : satiété moyenne ${fmt(s.mean,1)}/10 après le repas.`,`${s.count} repas portant ce nom et une satiété renseignée. 0 = aucune satiété, 10 = sensation très pleine.`));
  if(a.contexts.length)html+=`<h3>Les contextes que j’ai notés</h3>${a.contexts.slice(0,4).map(c=>`<p class="subtle">${esc(c.name)} · ${c.count} notes · faim ${fmt(c.mean,1)}/10</p>`).join('')}`;
  html+=`<p class="subtle">Ces observations décrivent des associations. Le sommeil, les émotions, les portions, le rythme et les notes manquantes peuvent aussi intervenir.</p></section>`;
  html+=`<section class="card"><h2>Mon corps et mon rythme</h2>`;
  if(a.bodyLink.correlation!=null)html+=insight(`Association entre les apports de la semaine et la variation du poids moyen la semaine suivante : r = ${fmt(a.bodyLink.correlation,2)}.`,`${a.bodyLink.count} paires de semaines consécutives, avec au moins 3 journées complètes et 2 pesées dans chacune. Association descriptive, sans preuve de cause ni mesure de graisse ou de muscle.`);
  else html+=`<p class="subtle">Le tableau rapproche les apports, la faim, le sport et les mesures semaine par semaine. Une association chiffrée demande au moins 5 paires de semaines consécutives suffisamment renseignées.</p>`;
  html+=a.weeks.length?`<div class="scroll-table"><table><caption class="sr-only">Suivi par semaine dans la période choisie</caption><thead><tr><th>Semaine</th><th>Poids</th><th>Apports</th><th>Faim</th><th>Sport</th><th>Taille</th></tr></thead><tbody>${a.weeks.map(w=>`<tr><td>${dateLabel(w.date,true)}</td><td>${fmt(w.weight,2)}<small>${w.weighings} pesées</small></td><td>${fmt(w.kcal)} kcal<small>${w.completeDays} j. complets</small></td><td>${fmt(w.hungerMean,1)}/10<small>${w.hunger.length} notes</small></td><td>${w.sport} min</td><td>${fmt(w.waist,1)} cm</td></tr>`).join('')}</tbody></table></div>`:empty('Les premières données alimenteront ce bilan.');
  html+=`<p class="subtle">Le poids seul ne distingue pas l’eau, la graisse et le muscle. Aucun objectif n’est ajusté automatiquement.</p></section><section class="card"><h2>Les chiffres jour par jour</h2>${a.days.length?`<div class="scroll-table"><table><caption class="sr-only">Apports notés par journée</caption><thead><tr><th>Date</th><th>Saisie</th><th>kcal</th><th>P (g)</th><th>G (g)</th><th>L (g)</th></tr></thead><tbody>${a.days.map(d=>`<tr><td>${dateLabel(d.date,true)}</td><td>${d.complete?'Complète':'Partielle'}</td><td>${fmt(d.k)}</td><td>${fmt(d.p,1)}</td><td>${fmt(d.c,1)}</td><td>${fmt(d.f,1)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucune journée saisie dans cette période.')}</section>`;
  $('analysis-content').innerHTML=html;
}
function renderData(){const last=db.settings.lastBackup;$('backup-status').textContent=last?'Dernier téléchargement demandé : '+new Date(last).toLocaleString('fr-FR')+'. Vérifie que le fichier a bien été conservé.':'Aucune sauvegarde téléchargée pour le moment.';$('storage-info').textContent=storage.storageMode()==='indexeddb'?'Le stockage local est actif. Une personne ayant accès à ce navigateur peut lire le journal.':'Stockage local de secours actif. Pense à sauvegarder régulièrement.';$('install-help').textContent=matchMedia('(display-mode: standalone)').matches?'L’application est déjà ouverte en mode installé.':pendingInstall?'Installation disponible sur cet appareil.':'Dans Chrome Android : menu ⋮ → Installer et créer un raccourci → Installer. Certaines versions affichent « Ajouter à l’écran d’accueil ».';}
function render(){renderDay();renderMeals();renderHunger();updateCategories();renderLibrary();renderFavorites();renderBody();renderAnalysis();renderData();}

// Les formulaires emploient des champs décimaux acceptant aussi la virgule.
const value=(id)=>$(id)?.value??'';
function numeric(id,{min=0,max=100000,optional=false}={}){const raw=value(id).trim().replace(',','.');if(raw===''&&optional)return null;const n=Number(raw);if(raw===''||!Number.isFinite(n)||n<min||n>max)throw Error(`Vérifie le champ « ${$(id)?.labels?.[0]?.textContent||id} ».`);return n;}
const field=(id,label,{type='text',val='',placeholder='',max=200}={})=>`<label for="${id}">${esc(label)}</label><input id="${id}" name="${id}" type="${type}" value="${esc(val)}" ${type==='text'?`maxlength="${max}"`:''} ${placeholder?`placeholder="${esc(placeholder)}"`:''}>`;
const decimal=(id,label,val='',placeholder='Facultatif')=>`<label for="${id}">${esc(label)}</label><input id="${id}" name="${id}" type="text" inputmode="decimal" value="${esc(val??'')}" maxlength="12" placeholder="${esc(placeholder)}">`;
const textarea=(id,label,val='',max=4000)=>`<label for="${id}">${esc(label)}</label><textarea id="${id}" name="${id}" maxlength="${max}" rows="3">${esc(val)}</textarea>`;
function select(id,label,options,val=''){return `<label for="${id}">${esc(label)}</label><select id="${id}" name="${id}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`;}
function scaleSelect(id,label,val){return select(id,label,[['','Non renseignée'],...Array.from({length:11},(_,i)=>[i,i+'/10'])],val??'');}
function tagFields(id,label,options,current=[]){return `<fieldset><legend>${esc(label)}</legend><div class="tag-list">${options.map((text,i)=>`<label class="tag-label" for="${id}-${i}"><input id="${id}-${i}" name="${id}" type="checkbox" value="${esc(text)}" ${current.includes(text)?'checked':''}>${esc(text)}</label>`).join('')}</div></fieldset>`;}
function dateTimeFields(data){return `<div class="two-cols">${field('e-date','Date',{type:'date',val:data.date||selectedDay})}${field('e-time','Heure',{type:'time',val:data.time||localTime()})}</div>`;}
function getDateTime(){const date=value('e-date'),time=value('e-time');if(!validDate(date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))throw Error('Renseigne une date et une heure valides.');return {date,time};}
function showEditor(kind,title,fields,id=null){editKind=kind;editId=id;dirty=false;$('editor-title').textContent=title;$('editor-fields').innerHTML=fields;$('editor-submit').textContent=kind==='settings'?'Garder mes repères':'Enregistrer';$('form-error').hidden=true;if(!$('editor').open)$('editor').showModal();document.body.classList.add('modal-open');$('editor').scrollTop=0;}
function hideEditor(){const returning=returnToMeal;returnToMeal=null;$('editor').close();document.body.classList.remove('modal-open');editKind=null;editId=null;dirty=false;if(returning){openMeal(returning.data,returning.id);dirty=true;}}
async function closeEditor(){if(dirty&&!await confirmBox('Fermer sans enregistrer ?','Tes modifications dans ce formulaire ne seront pas conservées.','Fermer'))return;hideEditor();}
function deletionButton(){return editId?'<div class="delete-area"><button type="button" data-action="delete-editing" class="button danger full">Supprimer cette entrée</button></div>':'';}

function openHunger(data={},id=null){
  const physical=['Creux dans l’estomac','Gargouillis','Baisse d’énergie','Tension','Salivation','Aucune sensation physique'],emotions=['Calme','Stress','Fatigue','Ennui','Joie','Tristesse','Frustration','Besoin de réconfort'];
  const allPhysical=[...new Set([...physical,...(data.physical||[])])],allEmotions=[...new Set([...emotions,...(data.emotions||[])])];
  showEditor('hunger',id?'Ma sensation notée':'Comment je me sens ?',dateTimeFields(data)+`<label for="e-intensity">Intensité de ma faim <output class="range-value" id="intensity-value">${data.intensity??5}/10</output></label><input id="e-intensity" name="e-intensity" type="range" min="0" max="10" step="1" value="${data.intensity??5}"><div class="scale-ends"><span>0 · aucune faim</span><span>10 · très forte faim</span></div>`+select('e-type','Ce que je ressens',['Faim physique','Envie de manger','Je ne sais pas','Aucune faim'],data.type||'Je ne sais pas')+select('e-period','Le moment',['À tout moment','Au réveil','Avant un repas','Après un repas','Entre les repas','Avant le sport','Après le sport','Soirée / nuit',...(data.period? [data.period]:[])],data.period||'À tout moment')+tagFields('physical','Dans mon corps (plusieurs choix)',allPhysical,data.physical)+tagFields('emotions','Mes émotions ou mon état (plusieurs choix)',allEmotions,data.emotions)+field('e-context','Le contexte (facultatif)',{val:data.context||'',placeholder:'Au travail, seule, repas tardif…',max:300})+textarea('e-note','Un mot de plus (facultatif)',data.note)+deletionFor(id),id);
}
function deletionFor(id){return id?'<div class="delete-area"><button type="button" data-action="delete-editing" class="button danger full">Supprimer cette entrée</button></div>':'';}
function mealDraft(){return {...getDateTime(),name:value('e-name').trim(),meal:value('e-meal'),items:structuredClone(draftItems),hunger:numeric('e-hunger',{optional:true,max:10}),satiety:numeric('e-satiety',{optional:true,max:10}),duration:numeric('e-duration',{optional:true,min:1,max:1440}),note:value('e-note')};}
function openMeal(data={},id=null){draftItems=structuredClone(data.items||[]);selectedFood=null;editItemId=null;
  const types=['Petit-déjeuner','Collation matin','Déjeuner','Collation après-midi','Dîner','Collation soirée','Autre / boisson'];
  showEditor('meal',id?'Mon repas noté':'Mon repas ou ma collation',dateTimeFields(data)+select('e-meal','Type de repas',types,data.meal||'Déjeuner')+field('e-name','Un nom (facultatif)',{val:data.name||'',placeholder:'Mon wrap poulet, déjeuner maison…'})+'<div id="draft-items" class="ingredient-list"></div><div id="draft-total" class="ingredient-total"></div><div class="field-group"><h3>Ajouter un aliment</h3>'+field('food-search','Chercher dans ma bibliothèque',{type:'search',placeholder:'Nom de l’aliment, cru ou cuit…'})+'<div id="picker-results" class="picker-results"></div><div id="selected-food" class="selected-food" hidden></div><div id="portion-fields" hidden><div class="two-cols">'+decimal('item-qty','Quantité',100,'Ex. 100')+select('item-unit','Unité',[['g','grammes']], 'g')+'</div><p id="portion-preview" class="field-hint"></p><button type="button" data-action="add-ingredient" id="add-ingredient" class="button secondary full">Ajouter à mon repas</button></div><button type="button" data-action="food-from-meal" class="text-button">+ Créer mon produit avec l’étiquette</button></div><div class="two-cols">'+scaleSelect('e-hunger','Faim avant le repas',data.hunger)+scaleSelect('e-satiety','Satiété après',data.satiety)+'</div><p class="field-hint">Faim : 0 = aucune, 10 = très forte. Satiété : 0 = aucune, 10 = sensation très pleine.</p>'+decimal('e-duration','Durée du repas (minutes)',data.duration)+textarea('e-note','Comment je l’ai vécu (facultatif)',data.note)+'<button type="button" data-action="save-favorite" class="button secondary full">♡ Garder ce repas en favori</button>'+deletionFor(id),id);
  renderDraft();renderPicker();
}
function renderDraft(){$('draft-items').innerHTML=draftItems.map(i=>`<div class="ingredient"><div><strong>${esc(i.name)}</strong><small>${fmt(i.qty,1)} ${i.unit==='portion'?'portion(s)':i.unit} · ${fmt(i.amount,1)} ${i.baseUnit} · ${esc(i.basis)}<br>${fmt(i.k)} kcal · P ${fmt(i.p,1)} · G ${fmt(i.c,1)} · L ${fmt(i.f,1)} g</small></div><button type="button" class="edit-button" data-action="edit-ingredient" data-id="${esc(i.id)}" aria-label="Modifier la portion de ${esc(i.name)}">${icon('edit')}</button><button type="button" class="remove-button" data-action="remove-ingredient" data-id="${esc(i.id)}" aria-label="Retirer ${esc(i.name)}">×</button></div>`).join('');const t=sumMacros(draftItems);$('draft-total').textContent=draftItems.length?`Total du repas : ${fmt(t.k)} kcal · P ${fmt(t.p,1)} · G ${fmt(t.c,1)} · L ${fmt(t.f,1)} g`:'Ajoute un ou plusieurs aliments à ce repas.';}
function renderPicker(){const q=normalize(value('food-search'));const foods=foodList().filter(f=>normalize(f.name+' '+f.basis).includes(q)).slice(0,16);$('picker-results').innerHTML=foods.length?foods.map(f=>`<button type="button" data-action="select-food" data-id="${esc(f.id)}" class="picker-result${selectedFood?.id===f.id?' selected':''}">${esc(f.name)} <span class="food-state">${esc(f.basis)}</span><small>${fmt(f.k)} kcal /100 ${f.unit}</small></button>`).join(''):'<p class="subtle">Ce produit n’est pas encore dans ta bibliothèque. Ajoute sa référence ci-dessous.</p>';}
function chooseFood(food,qty=100,unit=food.unit){selectedFood=food;$('selected-food').hidden=false;$('portion-fields').hidden=false;$('selected-food').textContent=food.name+' · '+food.basis+'. Valeurs pour 100 '+food.unit+'.';$('item-unit').innerHTML=`<option value="${food.unit}">${food.unit==='g'?'grammes':'millilitres'}</option><option value="portion">portion(s) de ${fmt(food.portion,1)} ${food.unit}</option>`;$('item-unit').value=unit;$('item-qty').value=qty;$('add-ingredient').textContent=editItemId?'Mettre à jour la portion':'Ajouter à mon repas';renderPicker();portionPreview();}
function portionPreview(){if(!selectedFood)return;try{const item=makeItem(selectedFood,numeric('item-qty',{min:.01,max:10000}),value('item-unit'));$('portion-preview').textContent=`${fmt(item.amount,1)} ${item.baseUnit} (${item.basis}) · ${fmt(item.k)} kcal · P ${fmt(item.p,1)} · G ${fmt(item.c,1)} · L ${fmt(item.f,1)} g`;}catch{$('portion-preview').textContent='Indique une quantité positive.';}}
function addIngredient(){if(!selectedFood)throw Error('Choisis un aliment.');const item=makeItem(selectedFood,numeric('item-qty',{min:.01,max:10000}),value('item-unit'));if(editItemId){item.id=editItemId;draftItems=draftItems.map(i=>i.id===editItemId?item:i);}else draftItems.push(item);dirty=true;selectedFood=null;editItemId=null;$('selected-food').hidden=true;$('portion-fields').hidden=true;$('food-search').value='';renderDraft();renderPicker();$('draft-total').scrollIntoView({block:'nearest'});}
function editIngredient(id){const item=draftItems.find(i=>i.id===id);if(!item)return;editItemId=id;const portion=item.unit==='portion'?item.amount/item.qty:foodList().find(f=>f.id===item.foodId)?.portion||100;const snapshot={id:item.foodId||'snapshot',name:item.name,basis:item.basis,unit:item.baseUnit,portion,...Object.fromEntries(MACROS.map(k=>[k,item[k]*100/item.amount]))};chooseFood(snapshot,item.qty,item.unit);$('item-qty').focus();}

function openFood(data={},id=null){
  showEditor('food',id?'Mon aliment personnalisé':'Ma référence alimentaire',field('e-name','Nom du produit',{val:data.name||'',placeholder:'Ex. HiPRO vanille, marque et format'})+select('e-basis','Poids de référence',['produit','cru / sec','cuit','égoutté','préparation maison',...(data.basis?[data.basis]:[])],data.basis||'produit')+select('e-unit','Valeurs sur l’étiquette',[['g','Pour 100 grammes'],['ml','Pour 100 millilitres']],data.unit||'g')+'<p class="field-hint">Recopie les valeurs pour 100 g ou 100 ml, puis indique le poids d’une portion. Exemple : une barre de 55 g ou un œuf de 50 g sans coquille.</p><div class="two-cols">'+decimal('food-k','Calories /100',data.k,'kcal')+decimal('food-p','Protéines /100',data.p,'g')+decimal('food-c','Glucides /100',data.c,'g')+decimal('food-f','Lipides /100',data.f,'g')+'</div>'+decimal('food-portion','Poids ou volume d’une portion',data.portion??100,'g ou ml')+select('food-category','Famille',['Mes aliments','Protéines','Féculents','Légumineuses','Légumes','Fruits','Laitages','Matières grasses','Boissons'],data.category||'Mes aliments')+textarea('food-source','Source ou précision (facultatif)',data.source||'Étiquette de mon produit.',500)+deletionFor(id),id);
}
function openBody(data={},id=null){const fields=Object.entries(BODY_FIELDS).map(([key,label])=>decimal('body-'+key,label+' ('+MEASUREMENT_UNIT(key)+')',data[key])).join('');showEditor('body',id?'Mes mesures notées':'Une mesure, à mon rythme',field('e-date','Date des mesures',{type:'date',val:data.date||selectedDay})+'<p class="field-hint">Tous les champs sont facultatifs. Une seule fiche par date ; tu peux la compléter plus tard.</p><div class="two-cols">'+fields+'</div>'+textarea('e-note','Conditions ou remarques (facultatif)',data.note,2000)+deletionFor(id),id);}
function openSport(data={},id=null){showEditor('sport',id?'Mon activité notée':'Un peu de mouvement',dateTimeFields(data)+select('e-type','Activité',['Musculation bas du corps','Musculation haut du corps','Musculation','Marche','Vélo / Sprint','Cours collectif / ROM','Mobilité','Autre',...(data.type?[data.type]:[])],data.type||'Musculation')+decimal('e-duration','Durée (minutes)',data.duration,'Ex. 45')+scaleSelect('e-effort','Effort ressenti (facultatif)',data.effort)+'<p class="field-hint">0 = très facile, 10 = effort maximal. Les calories dépensées ne sont pas déduites des apports.</p>'+textarea('e-note','Comment je l’ai vécu (facultatif)',data.note)+deletionFor(id),id);}
function openSettings(){const s=db.settings;showEditor('settings','Mes repères personnels','<p class="subtle">Aucun objectif imposé. Laisse les champs vides ou saisis les repères que tu souhaites suivre avec ta diététicienne. Ce sont des points de comparaison, pas des prescriptions médicales.</p><div class="two-cols">'+decimal('setting-kcal','Calories (kcal / jour)',s.kcal)+decimal('setting-protein','Protéines (g / jour)',s.protein)+decimal('setting-carbs','Glucides (g / jour)',s.carbs)+decimal('setting-fat','Lipides (g / jour)',s.fat)+'</div>'+decimal('setting-weight','Poids repère (kg)',s.weight)+'<p class="field-hint">Les repères ne changent pas automatiquement selon ton poids ou ton activité.</p>');}

async function saveEditor(){if(busy)return;busy=true;$('editor-submit').disabled=true;$('form-error').hidden=true;const kind=editKind,currentId=editId;let dateToShow=null;
  try{
    if(kind==='hunger'){const e={id:currentId||uid(),kind:'hunger',...getDateTime(),intensity:numeric('e-intensity',{max:10}),type:value('e-type'),period:value('e-period'),physical:[...document.querySelectorAll('input[name=physical]:checked')].map(i=>i.value),emotions:[...document.querySelectorAll('input[name=emotions]:checked')].map(i=>i.value),context:value('e-context').trim(),note:value('e-note')};await commit(d=>upsertEntry(d,e));dateToShow=e.date;}
    if(kind==='meal'){const draft=mealDraft();if(!draft.items.length)throw Error('Ajoute au moins un aliment au repas.');if(editItemId||selectedFood)throw Error('Touche d’abord « Ajouter à mon repas » ou termine la modification de la portion.');const e={id:currentId||uid(),kind:'meal',...draft};await commit(d=>upsertEntry(d,e));dateToShow=e.date;}
    if(kind==='sport'){const e={id:currentId||uid(),kind:'sport',...getDateTime(),type:value('e-type'),duration:numeric('e-duration',{min:1,max:1440}),effort:numeric('e-effort',{optional:true,max:10}),note:value('e-note')};await commit(d=>{upsertEntry(d,e);d.days[e.date]||={complete:false,activityKnown:false,note:''};d.days[e.date].activityKnown=true;});dateToShow=e.date;}
    if(kind==='food'){const name=value('e-name').trim();if(!name)throw Error('Donne un nom à cet aliment.');const f={id:currentId||uid(),name,basis:value('e-basis'),unit:value('e-unit'),portion:numeric('food-portion',{min:.1,max:10000}),category:value('food-category'),source:value('food-source')};for(const k of MACROS)f[k]=numeric('food-'+k,{max:k==='k'?2000:100});await commit(d=>{if(currentId)d.foods=d.foods.map(x=>x.id===currentId?f:x);else d.foods.push(f);});const returning=returnToMeal;hideEditor();if(returning)chooseFood(f,100,f.unit);toast('Aliment gardé dans ta bibliothèque.');return;}
    if(kind==='body'){const date=value('e-date');if(!validDate(date))throw Error('Choisis une date valide.');const b={id:currentId||uid(),date,note:value('e-note')};let count=0;for(const k of Object.keys(BODY_FIELDS)){const n=numeric('body-'+k,{min:.1,max:1000,optional:true});if(n!=null){b[k]=n;count++;}}if(!count)throw Error('Note au moins une mesure.');const existing=db.body.find(x=>x.date===date&&x.id!==currentId);if(existing&&!await confirmBox('Une fiche existe à cette date','Les mesures remplies seront ajoutées ou mises à jour sur la fiche existante. Les champs laissés vides conserveront leur valeur.','Compléter'))return;
      await commit(d=>{const same=d.body.find(x=>x.date===date&&x.id!==currentId);if(same){Object.keys(BODY_FIELDS).forEach(k=>{if(b[k]!=null)same[k]=b[k];});if(b.note)same.note=b.note;if(currentId)d.body=d.body.filter(x=>x.id!==currentId);}else{const idx=d.body.findIndex(x=>x.id===currentId);if(idx<0)d.body.push(b);else d.body[idx]=b;}});dateToShow=date;}
    if(kind==='settings'){const s={kcal:numeric('setting-kcal',{optional:true,min:.1,max:20000}),protein:numeric('setting-protein',{optional:true,min:.1,max:2000}),carbs:numeric('setting-carbs',{optional:true,min:.1,max:2000}),fat:numeric('setting-fat',{optional:true,min:.1,max:2000}),weight:numeric('setting-weight',{optional:true,min:.1,max:2000})};await commit(d=>Object.assign(d.settings,s));}
    hideEditor();if(dateToShow)setDay(dateToShow);toast(kind==='settings'?'Repères personnels enregistrés.':'C’est noté dans ton journal.');
  }catch(e){$('form-error').textContent=e.message;$('form-error').hidden=false;$('form-error').scrollIntoView({block:'nearest'});}finally{busy=false;$('editor-submit').disabled=false;}
}
function upsertEntry(d,e){const index=d.entries.findIndex(x=>x.id===e.id);if(index>=0)d.entries[index]=e;else d.entries.push(e);}
function confirmBox(title,message,accept='Confirmer',extra=''){
  if(confirmResolve)return Promise.resolve(false);$('confirm-title').textContent=title;$('confirm-message').textContent=message;$('confirm-accept').textContent=accept;$('confirm-extra').innerHTML=extra;$('confirm-dialog').showModal();return new Promise(resolve=>confirmResolve=resolve);
}
function resolveConfirm(result){const resolver=confirmResolve;confirmResolve=null;$('confirm-dialog').close();resolver?.(result);}
async function deleteEditing(){const kind=editKind,id=editId;if(!await confirmBox('Supprimer cette entrée ?','La suppression concerne uniquement cette entrée sur cet appareil.','Supprimer'))return;await commit(d=>{if(kind==='body')d.body=d.body.filter(x=>x.id!==id);else if(kind==='food')d.foods=d.foods.filter(x=>x.id!==id);else d.entries=d.entries.filter(x=>x.id!==id);});returnToMeal=null;hideEditor();toast('Entrée supprimée.');}
async function saveFavorite(){if(!draftItems.length)throw Error('Compose ton repas avant de le garder en favori.');if(editItemId||selectedFood)throw Error('Ajoute ou mets à jour l’aliment sélectionné avant de garder le favori.');const data=mealDraft();const accepted=await confirmBox('Garder mon repas en favori','Les aliments et les portions seront conservés, sans ajouter de repas au journal.','Garder',field('favorite-name','Nom du favori',{val:data.name||data.meal,max:200}));const name=value('favorite-name').trim();if(!accepted)return;if(!name)throw Error('Donne un nom au favori.');await commit(d=>d.favorites.push({id:uid(),name,meal:data.meal,items:data.items}));toast('Repas gardé en favori. Tu peux encore enregistrer le repas du jour.');}

function reportOptions(){const {start,end}=validPeriod($('report-start').value,$('report-end').value,365);return {start,end,name:$('report-name').value.trim(),note:$('report-note').value.trim(),detail:$('report-detail').checked};}
async function pdfDownload(){const button=$('download-pdf');button.disabled=true;$('report-status').textContent='Je prépare ton rapport…';try{const opts=reportOptions();await commit(d=>{d.settings.reportName=opts.name;d.settings.reportNote=opts.note;});const bytes=await createReport(db,opts);download(`GP-Nutrition-${opts.start}-${opts.end}.pdf`,bytes,'application/pdf');$('report-status').textContent='Rapport prêt. Retrouve le PDF dans les téléchargements de ton téléphone.';}catch(e){$('report-status').textContent=e.message;}finally{button.disabled=false;}}
async function backup(){const date=new Date().toISOString();await commit(d=>d.settings.lastBackup=date);download('GP-Nutrition-sauvegarde-'+localDate()+'.json',JSON.stringify(backupObject(db),null,2),'application/json');toast('Sauvegarde téléchargée. Vérifie le fichier dans Téléchargements.');}
async function restore(file){if(!file)return;if(file.size>15*1024*1024)throw Error('Cette sauvegarde est trop volumineuse (15 Mo maximum).');const restored=parseBackup(await file.text());const n=restored.entries.length;const accepted=await confirmBox('Restaurer cette sauvegarde ?',`${n} événements, ${restored.body.length} fiches de mesures, ${restored.foods.length} aliments personnalisés et ${restored.favorites.length} favoris. Elle remplacera le journal actuel sur cet appareil.`, 'Restaurer','<label class="check-line"><input id="restore-safety" type="checkbox" checked><span>Télécharger d’abord une copie du journal actuel</span></label>');const safety=$('restore-safety')?.checked;if(!accepted)return;if(safety&&!loadError)download('GP-Nutrition-avant-restauration-'+localDate()+'.json',JSON.stringify(backupObject(db),null,2),'application/json');await commit(d=>{for(const k of Object.keys(d))delete d[k];Object.assign(d,restored);},{recover:loadError});noteDrafts.clear();render();$('report-name').value=db.settings.reportName;$('report-note').value=db.settings.reportNote;if(loadError===false)$('system-notices').querySelectorAll('.error').forEach(x=>x.remove());toast('Sauvegarde restaurée.');}

async function install(){if(pendingInstall){await pendingInstall.prompt();await pendingInstall.userChoice;pendingInstall=null;renderData();}else{goPage('review');reviewView('data');toast(matchMedia('(display-mode: standalone)').matches?'Cette application est déjà installée.':'Chrome : menu ⋮ → Installer et créer un raccourci → Installer.');}}
async function registerSW(){if(!('serviceWorker' in navigator)){notice('Le mode hors ligne n’est pas disponible dans ce navigateur.');return;}if(!window.isSecureContext){notice('Pour installer l’application, ouvre sa future adresse HTTPS GitHub Pages dans Chrome.');return;}
  try{const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});
    const updateNotice=worker=>{waitingWorker=worker;const e=notice('Une nouvelle version est prête. Termine ta saisie avant de la charger.');const b=document.createElement('button');b.className='text-button';b.dataset.action='update-app';b.textContent='Mettre à jour';e.append(b);};
    if(registration.waiting)updateNotice(registration.waiting);registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)updateNotice(worker);});});
    let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(waitingWorker&&!refreshing){refreshing=true;location.reload();}});
  }catch{notice('Le mode hors ligne n’a pas pu se préparer. Vérifie la connexion puis recharge la page.');}
}

document.addEventListener('click',async event=>{
  const button=event.target.closest('button');if(!button)return;
  try{
    if(button.dataset.page){goPage(button.dataset.page);return;}if(button.dataset.mealView){mealView(button.dataset.mealView);return;}if(button.dataset.reviewView){reviewView(button.dataset.reviewView);return;}
    const action=button.dataset.action,id=button.dataset.id;
    switch(action){
      case 'previous-day':setDay(shiftDate(selectedDay,-1));break;case 'next-day':setDay(shiftDate(selectedDay,1));break;case 'today':setDay(localDate());break;
      case 'new-meal':returnToMeal=null;openMeal();break;case 'new-hunger':openHunger();break;case 'new-sport':openSport();break;case 'new-body':openBody();break;case 'settings':openSettings();break;
      case 'close-editor':await closeEditor();break;case 'confirm-cancel':resolveConfirm(false);break;case 'confirm-accept':resolveConfirm(true);break;
      case 'edit-entry':{const e=db.entries.find(x=>x.id===id);if(e?.kind==='meal')openMeal(e,e.id);if(e?.kind==='hunger')openHunger(e,e.id);if(e?.kind==='sport')openSport(e,e.id);break;}
      case 'edit-body':{const b=db.body.find(x=>x.id===id);if(b)openBody(b,b.id);break;}
      case 'new-food':returnToMeal=null;openFood();break;case 'edit-food':{const f=db.foods.find(x=>x.id===id);if(f)openFood(f,f.id);break;}
      case 'food-from-meal':{returnToMeal={data:mealDraft(),id:editId};openFood();break;}
      case 'food-detail':{const f=foodList().find(x=>x.id===id);if(f)await confirmBox(f.name+' · '+f.basis,`${fmt(f.k)} kcal, ${fmt(f.p,1)} g de protéines, ${fmt(f.c,1)} g de glucides et ${fmt(f.f,1)} g de lipides pour 100 ${f.unit}. Une portion : ${fmt(f.portion,1)} ${f.unit}. ${f.source}`,'Compris');break;}
      case 'select-food':{const f=foodList().find(x=>x.id===id);if(f){editItemId=null;chooseFood(f);$('portion-fields').scrollIntoView({block:'nearest'});}break;}
      case 'add-ingredient':addIngredient();break;case 'edit-ingredient':editIngredient(id);break;case 'remove-ingredient':draftItems=draftItems.filter(x=>x.id!==id);if(editItemId===id){editItemId=null;selectedFood=null;$('portion-fields').hidden=true;$('selected-food').hidden=true;}dirty=true;renderDraft();break;
      case 'delete-editing':await deleteEditing();break;case 'save-favorite':await saveFavorite();break;
      case 'use-favorite':{const f=db.favorites.find(x=>x.id===id);if(f)openMeal({name:f.name,meal:f.meal,items:f.items.map(i=>({...i,id:uid()}))});break;}
      case 'delete-favorite':if(await confirmBox('Supprimer ce favori ?','Les repas déjà notés resteront dans le journal.','Supprimer')){await commit(d=>d.favorites=d.favorites.filter(x=>x.id!==id));toast('Favori supprimé.');}break;
      case 'save-day-note':{const date=selectedDay,note=value('day-note');await commit(d=>{d.days[date]||={complete:false,activityKnown:false,note:''};d.days[date].note=note;});noteDrafts.delete(date);toast('Ton mot est enregistré.');break;}
      case 'more-body':bodyLimit+=30;renderBody();break;
      case 'range-7':case 'range-28':case 'range-90':{const n=Number(action.split('-')[1]);$('analysis-start').value=shiftDate(selectedDay,-n+1);$('analysis-end').value=selectedDay;renderAnalysis();break;}
      case 'backup':button.disabled=true;try{await backup();}finally{button.disabled=false;}break;
      case 'restore':$('restore-file').click();break;
      case 'export-csv':download('GP-Nutrition-suivi-'+localDate()+'.csv',toCSV(db,'1900-01-01','2200-12-31'),'text/csv;charset=utf-8');toast('Suivi CSV téléchargé.');break;
      case 'download-pdf':await pdfDownload();break;case 'print-report':printReport(db,reportOptions());break;
      case 'persist-storage':{const granted=await navigator.storage?.persist?.();toast(granted?'Chrome conserve le stockage autant que possible.':'Chrome n’a pas accordé la protection. Tu peux toujours télécharger une sauvegarde.');break;}
      case 'install':await install();break;
      case 'update-app':if($('editor').open){toast('Ferme ou enregistre ton formulaire avant la mise à jour.');break;}waitingWorker?.postMessage({type:'SKIP_WAITING'});break;
      case 'erase':{if(!await confirmBox('Effacer tout mon journal ?','Cette action est définitive sur cet appareil. Les sauvegardes téléchargées restent disponibles. Écris EFFACER pour confirmer.','Effacer',field('erase-word','Confirmation',{max:20})))break;if(value('erase-word')!=='EFFACER'){toast('Les données sont conservées.');break;}await commit(d=>{const clean=emptyState();for(const k of Object.keys(d))delete d[k];Object.assign(d,clean);});noteDrafts.clear();await storage.removeLegacy();$('report-name').value='';$('report-note').value='';render();toast('Journal effacé sur cet appareil.');break;}
    }
  }catch(e){if($('editor').open){$('form-error').textContent=e.message;$('form-error').hidden=false;$('form-error').scrollIntoView({block:'nearest'});}else toast(e.message);}
});
document.addEventListener('input',event=>{const id=event.target.id;if(event.target.closest('#editor-form'))dirty=true;if(id==='e-intensity')$('intensity-value').textContent=value(id)+'/10';if(id==='food-search')renderPicker();if(id==='item-qty')portionPreview();if(id==='library-search')renderLibrary();if(id==='day-note')noteDrafts.set(selectedDay,value(id));});
document.addEventListener('change',async event=>{const id=event.target.id;try{if(id==='day')setDay(value(id));if(id==='library-category')renderLibrary();if(id==='body-field'||id==='body-range')renderBody();if(id==='analysis-start'||id==='analysis-end')renderAnalysis();if(id==='item-unit'){if(value(id)==='portion')$('item-qty').value=1;else $('item-qty').value=100;portionPreview();}
  if(id==='day-complete'||id==='activity-known'){const date=selectedDay,on=event.target.checked;await commit(d=>{d.days[date]||={complete:false,activityKnown:false,note:''};d.days[date][id==='day-complete'?'complete':'activityKnown']=on;});}
  if(id==='restore-file'){const file=event.target.files[0];event.target.value='';await restore(file);}
}catch(e){toast(e.message);render();}});
$('editor-form').addEventListener('submit',event=>{event.preventDefault();saveEditor();});
$('editor').addEventListener('cancel',event=>{event.preventDefault();closeEditor();});$('confirm-dialog').addEventListener('cancel',event=>{event.preventDefault();resolveConfirm(false);});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();pendingInstall=event;renderData();});window.addEventListener('appinstalled',()=>{pendingInstall=null;renderData();toast('GROS PÉTARD est installé.');});
channel?.addEventListener('message',async()=>{if($('editor').open){toast('Le journal a changé dans un autre onglet. Termine ou ferme ton formulaire, puis recharge cette page.');return;}try{db=await storage.reload();render();}catch{notice('Le journal a changé mais n’a pas pu être relu. Recharge cette page.',true);}});
window.addEventListener('beforeunload',event=>{if(dirty||noteDrafts.size){event.preventDefault();event.returnValue='';}});

$('day').value=selectedDay;$('analysis-start').value=shiftDate(selectedDay,-27);$('analysis-end').value=selectedDay;$('report-start').value=shiftDate(selectedDay,-27);$('report-end').value=selectedDay;
$('body-field').innerHTML=Object.entries(BODY_FIELDS).map(([k,label])=>`<option value="${k}">${label} (${MEASUREMENT_UNIT(k)})</option>`).join('');
try{const loaded=await storage.load();db=loaded.state;if(loaded.migrated)notice('Ton journal V1 a été repris sur cet appareil. Les aliments à la même heure ont été réunis en repas. Les anciens repères ont été conservés ; tu peux les revoir dans les réglages.');}
catch(e){loadError=true;notice('Le journal local n’a pas pu être lu. Il est conservé sans modification. Restaure une sauvegarde depuis Bilan → Mes données. '+e.message,true);}
$('report-name').value=db.settings.reportName;$('report-note').value=db.settings.reportNote;render();registerSW();
